using System.Text.Json;using Microsoft.Data.Sqlite;using WAID.Application.Abstractions;namespace WAID.Infrastructure.Persistence;public sealed class SqliteSecurityPostureRepository(WaidDatabase db):ISecurityPostureRepository{private static readonly JsonSerializerOptions O=new(JsonSerializerDefaults.Web);public async Task<SecurityPostureReport?> GetLatestAsync(CancellationToken t){await using var c=db.OpenConnection();await using var q=c.CreateCommand();q.CommandText="SELECT report_json FROM security_posture_runs ORDER BY generated_utc DESC LIMIT 1";var j=await q.ExecuteScalarAsync(t) as string;return j is null?null:JsonSerializer.Deserialize<SecurityPostureReport>(j,O);}public async Task SaveAsync(SecurityPostureSnapshot s,SecurityPostureReport r,CancellationToken t){await using var c=db.OpenConnection();await using var tx=(SqliteTransaction)await c.BeginTransactionAsync(t);await using var q=c.CreateCommand();q.Transaction=tx;q.CommandText="INSERT INTO security_posture_runs(id,generated_utc,snapshot_json,report_json,acknowledgements_json)VALUES($id,$time,$s,$r,$a)";q.Parameters.AddWithValue("$id",r.Id.ToString());q.Parameters.AddWithValue("$time",r.GeneratedAtUtc.ToString("O"));q.Parameters.AddWithValue("$s",JsonSerializer.Serialize(s,O));q.Parameters.AddWithValue("$r",JsonSerializer.Serialize(r,O));q.Parameters.AddWithValue("$a",JsonSerializer.Serialize(r.AcknowledgedExceptions,O));await q.ExecuteNonQueryAsync(t);await tx.CommitAsync(t);}}
